// Cloudflare Worker entry: the OpenNext build of the dashboard (fetch) plus the 5-minute cron.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore — generated by `opennextjs-cloudflare build` (absent until the first build)
import { default as handler } from "./.open-next/worker.js";
import { runCron } from "./src/lib/cron";

export default {
  fetch: handler.fetch,
  async scheduled(_event, env, ctx) {
    ctx.waitUntil(runCron(env as never));
  },
} satisfies ExportedHandler<Cloudflare.Env>;
